import time
import smbus2

# I2C bus and device address
I2C_BUS = 1
AMG8833_ADDR = 0x69

# Initialize I2C bus
bus = smbus2.SMBus(I2C_BUS)

def read_temperature(reg_addr):
    """Read a temperature value from the AMG8833 register."""
    try:
        value = bus.read_i2c_block_data(AMG8833_ADDR, reg_addr, 2)
        return ((value[1] << 8) | value[0]) / 1000.0  # Convert to Celsius
    except Exception as e:
        print(f"Error reading temperature: {e}")
        return None

def main():
    try:
        while True:
            for i in range(8, 24):
                temp = read_temperature(i * 2)
                if temp is not None:
                    print(f"Pixel {i}: {temp:.2f}°C")
            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user. Exiting cleanly...")
    finally:
        # Release resources
        bus.close()
        print("I2C bus released.")

if __name__ == "__main__":
    main()

