    baudrate = 9600  # Change this to your baudrate

    reader = SerialReader(port, baudrate)
    reader_thread = threading.Thread(target=reader.read)
    reader_thread.start()

    reader_thread.join(3)  # Allow 3 seconds for readings

    reader.close()
    print("Serial port closed.")

