from gpiozero.pins.pigpio import PWMOutputPigpio
import signal

class PWMReporter:
    def __init__(self, pins=[4, 17, 22, 27]):
        self.pins = pins
        self.pwm_devices = {}
        self.setup()

    def setup(self):
        for pin in self.pins:
            try:
                self.pwm_devices[pin] = PWMOutputPigpio(pin)
            except Exception as e:
                print(f"Error initializing PWM on pin {pin}: {e}")
                sys.exit(1)

    def report_state(self):
        for pin, device in self.pwm_devices.items():
            try:
                state = device.value
                print(f"PWM on pin {pin}: {state}%")
            except Exception as e:
                print(f"Error reading PWM from pin {pin}: {e}")
                continue

    def run(self):
        try:
            while True:
                self.report_state()
                time.sleep(1)
        except KeyboardInterrupt:
            print("Program interrupted by user")
        finally:
            for device in self.pwm_devices.values():
                device.close()
            print("All PWM devices closed, exiting.")

if __name__ == "__main__":
    reporter = PWMReporter()
    signal.signal(signal.SIGINT, reporter.run)
    reporter.run()

